SELECT count(*) FROM (
    SELECT mode(v) OVER (ORDER BY r ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS m FROM modes_str
) WHERE m NOT IN (repeat('x', 50), repeat('y', 5), repeat('z', 100));

