SELECT i,
       lead(v, i % 3, -i ORDER BY peer DESC, i) OVER (
           ORDER BY i ROWS BETWEEN 2 PRECEDING AND 3 FOLLOWING
       ),
       lag(v, i % 2, i + 100 ORDER BY peer, i DESC) OVER (
           ORDER BY i ROWS BETWEEN 3 PRECEDING AND 2 FOLLOWING
       )
FROM value_edges;

